create or replace function public.ssr_air_timeseries_run_create(p_provider_code text,p_lat double precision,p_lon double precision,p_payload jsonb) returns uuid language plpgsql security definer set search_path=public,ecology as $$ declare v_id uuid; begin insert into ecology.ssr_air_timeseries_runs(provider_code,requested_latitude,requested_longitude,request_payload,status,started_at) values(p_provider_code,p_lat,p_lon,p_payload,'running',now()) returning id into v_id; return v_id; end $$;
create or replace function public.ssr_air_timeseries_run_finish(p_id uuid,p_status text,p_profile_ids uuid[],p_succeeded integer,p_failed integer,p_summary jsonb) returns boolean language plpgsql security definer set search_path=public,ecology as $$ begin update ecology.ssr_air_timeseries_runs set status=p_status,profile_ids=coalesce(p_profile_ids,'{}'::uuid[]),succeeded_count=p_succeeded,failed_count=p_failed,result_summary=coalesce(p_summary,'{}'::jsonb),completed_at=now(),updated_at=now() where id=p_id; return found; end $$;
revoke all on function public.ssr_air_timeseries_run_create(text,double precision,double precision,jsonb) from public,anon,authenticated;
revoke all on function public.ssr_air_timeseries_run_finish(uuid,text,uuid[],integer,integer,jsonb) from public,anon,authenticated;
grant execute on function public.ssr_air_timeseries_run_create(text,double precision,double precision,jsonb) to service_role;
grant execute on function public.ssr_air_timeseries_run_finish(uuid,text,uuid[],integer,integer,jsonb) to service_role;
